const key = `order-${orderId}`;   // 클라이언트가 만들고 재시도 시 동일하게
await pg.charge({ amount, currency }, { idempotencyKey: key });
// PG 가 같은 키의 두 번째 요청에 「첫 결과」를 그대로 돌려준다

-- 주문당 결제 한 건만 허용
CREATE UNIQUE INDEX ON payments (order_id) WHERE status <> 'failed';

-- 또는 멱등 키 테이블
INSERT INTO idem_keys (key) VALUES ($1) ON CONFLICT DO NOTHING;
-- 0 행이면 이미 처리한 요청

const seen = await db.markWebhookSeen(event.id);   // 이미 있으면 false
if (!seen) return res.sendStatus(200);            // 조용히 성공 응답
await handle(event);
